(function () {
    'use strict';

    var TWO_PI = Math.PI * 2;

    // Approved slot sounds bundled locally: no external requests or autoplay.
    function createWheelSound() {
        var encoded = { reels: '', jackpot: '' };
        var audio = null, buffers = null, ready = null, voices = [];
        var enabled = true, allowed = false, epoch = 0;
        function stop() {
            epoch++;
            voices.forEach(function (voice) { try { voice.stop(); voice.disconnect(); } catch (ignore) {} });
            voices = [];
        }
        function prime() {
            if (!enabled) return;
            allowed = true;
            try {
                var Audio = window.AudioContext || window.webkitAudioContext;
                if (!Audio) return;
                if (!audio || audio.state === 'closed') { audio = new Audio(); ready = null; }
                var current = audio;
                // Resume immediately inside the button gesture, before awaiting decode.
                var resume = current.state === 'suspended' ? current.resume() : Promise.resolve();
                if (buffers) ready = Promise.resolve(buffers);
                if (!ready) {
                    var decode = buffers ? Promise.resolve(buffers) : Promise.all(['reels', 'jackpot'].map(function (key) {
                        var raw = window.atob(encoded[key]), bytes = new Uint8Array(raw.length);
                        for (var i = 0; i < raw.length; i++) bytes[i] = raw.charCodeAt(i);
                        return new Promise(function (resolve, reject) { current.decodeAudioData(bytes.buffer, resolve, reject); });
                    })).then(function (decoded) { buffers = decoded; return buffers; });
                    ready = decode.catch(function () { return null; });
                }
                ready = Promise.all([ready, resume]).then(function (results) { return results[0]; }).catch(function () { return null; });
            } catch (ignore) { audio = null; ready = null; }
        }
        function play(index, duration) {
            if (!enabled || !allowed || !audio || !ready) return;
            var request = epoch, started = performance.now(), current = audio;
            ready.then(function (decoded) {
                if (!decoded || request !== epoch || !enabled || !allowed || document.hidden || current.state !== 'running') return;
                try {
                    var source = current.createBufferSource(), buffer = decoded[index];
                    var rate = duration ? buffer.duration / (duration / 1000) : 1;
                    // A slow first decode joins the reel track in sync; no delayed sound replay.
                    var elapsed = (performance.now() - started) / 1000;
                    if (duration && elapsed >= duration / 1000) return;
                    if (!duration && elapsed > 1) return;
                    source.buffer = buffer; source.playbackRate.value = rate;
                    source.connect(current.destination); voices.push(source);
                    source.onended = function () { source.disconnect(); voices = voices.filter(function (v) { return v !== source; }); };
                    source.start(0, duration ? elapsed * rate : 0);
                } catch (ignore) { /* Keep the wheel working when audio is unavailable. */ }
            });
        }
        return {
            prime: prime,
            enabled: function (value) { enabled = value; if (!enabled) stop(); },
            effect: function () { /* Reserved for approved shared UI effects. */ },
            spin: function (duration) { if (duration > 0) play(0, duration); },
            win: function () { stop(); play(1, 0); },
            stop: stop,
            close: function () {
                allowed = false; stop();
                if (audio) { try { audio.close().catch(function () {}); } catch (ignore) {} }
                audio = null; ready = null;
            }
        };
    }

    function value(item, name) {
        if (!item) return undefined;
        return item[name] !== undefined
            ? item[name] : item[name.charAt(0).toLowerCase() + name.slice(1)];
    }

    function isSeries(item) {
        return String(value(item, 'Type') || '').toLowerCase() === 'series';
    }

    function idOf(item) { return String(value(item, 'Id') || ''); }
    function nameOf(item) { return String(value(item, 'Name') || 'Unknown'); }

    function matchesRuntime(item, maxMinutes) {
        if (!maxMinutes) return true;
        var ticks = Number(value(item, 'RunTimeTicks'));
        return Number.isFinite(ticks) && ticks > 0 && ticks <= maxMinutes * 600000000;
    }

    function matchesRating(item, minimum) {
        if (!minimum) return true;
        var raw = value(item, 'CommunityRating');
        var rating = Number(raw);
        return raw != null && Number.isFinite(rating) && rating >= minimum && rating <= 10;
    }

    function runtimeLabel(item) {
        var ticks = Number(value(item, 'RunTimeTicks'));
        return Number.isFinite(ticks) && ticks > 0
            ? Math.ceil(ticks / 600000000) + ' min' + (isSeries(item) ? ' next episode' : '')
            : 'Runtime unknown';
    }

    function playbackTarget(item) {
        var id = isSeries(item) ? value(item, 'NextEpisodeId') : idOf(item);
        if (!id) return null;
        var ticks = Number(value(item, 'PlaybackPositionTicks'));
        return {
            id: String(id),
            ticks: Number.isFinite(ticks) && ticks > 0 ? Math.floor(ticks) : 0
        };
    }

    function episodeCode(item) {
        var season = value(item, 'NextSeasonNumber');
        var episode = value(item, 'NextEpisodeNumber');
        return season == null || episode == null ? ''
            : 'S' + String(season).padStart(2, '0')
                + 'E' + String(episode).padStart(2, '0');
    }

    function timeLabel(ticks) {
        var seconds = Math.floor(ticks / 10000000);
        var minutes = Math.floor(seconds / 60);
        return minutes + ':' + String(seconds % 60).padStart(2, '0');
    }

    function isAndroidClient() {
        return /Android/i.test(window.navigator && window.navigator.userAgent || '');
    }

    function normalizedUserId(id) {
        return String(id || '').replace(/-/g, '').toLowerCase();
    }

    async function sendSessionPlayback(target) {
        var api = window.ApiClient;
        if (!api || typeof api.deviceId !== 'function'
            || typeof api.getCurrentUserId !== 'function'
            || typeof api.getJSON !== 'function' || typeof api.ajax !== 'function') {
            throw new Error('The authenticated Jellyfin session API is unavailable.');
        }
        var deviceId = api.deviceId();
        var userId = api.getCurrentUserId();
        var serverId = typeof api.serverId === 'function' ? api.serverId() : '';
        if (!deviceId || !userId) {
            throw new Error('Cannot identify this browser and its signed-in user. Reload Jellyfin.');
        }
        var query = new URLSearchParams();
        query.set('DeviceId', deviceId);
        var sessions = await api.getJSON(api.getUrl('Sessions?' + query.toString()));
        if (!Array.isArray(sessions)) {
            throw new Error('Jellyfin returned an unexpected session list.');
        }
        // Never fall back to an arbitrary session or another playback device.
        var matches = sessions.filter(function (session) {
            return value(session, 'DeviceId') === deviceId
                && normalizedUserId(value(session, 'UserId')) === normalizedUserId(userId);
        });
        if (matches.length !== 1) {
            throw new Error(matches.length ? 'Multiple matching browser sessions were found. Reload Jellyfin.'
                : 'This browser session was not found. Reload Jellyfin and try again.');
        }
        var session = matches[0];
        if (!value(session, 'Id')) {
            throw new Error('This browser session has no session identifier.');
        }
        if (value(session, 'SupportsRemoteControl') !== true) {
            throw new Error('This browser session is not accepting playback commands. Reload Jellyfin and try again.');
        }
        if (normalizedUserId(api.getCurrentUserId()) !== normalizedUserId(userId)
            || (typeof api.serverId === 'function' ? api.serverId() : '') !== serverId) {
            throw new Error('Account or server changed. Reload WatchWheel.');
        }
        var command = new URLSearchParams();
        command.set('ItemIds', target.id);
        command.set('PlayCommand', 'PlayNow');
        command.set('StartPositionTicks', String(target.ticks));
        try {
            await api.ajax({
                type: 'POST',
                url: api.getUrl('Sessions/' + encodeURIComponent(value(session, 'Id'))
                    + '/Playing?' + command.toString())
            });
        } catch (error) {
            var status = error && (error.status || error.statusCode);
            throw new Error('Jellyfin rejected the playback command'
                + (status ? ' (HTTP ' + status + ')' : '') + '.');
        }
    }

    function createApp(page) {
        var state = {
            items: [], pool: [], removed: new Set(), history: [], winner: null, rotation: 0,
            watchers: [], assignmentItem: null, spinning: false, loading: false, playing: false,
            request: 0, appliedFilters: null, candidatePage: 0, playbackTimer: null, filtersLoaded: false, contextChanged: false
        };
        function byId(id) { return page.querySelector('#' + id); }
        var canvas = byId('watchWheelCanvas');
        var context = canvas.getContext('2d');
        var wheelSound = createWheelSound(), soundEnabled = true, showChoices = true, activeSkin = 'classic';
        function message(text) { byId('wwMessage').textContent = text || ''; }
        function count() { byId('candidateCount').textContent = String(eligibleItems().length); }
        function busy() { return state.contextChanged || state.spinning || state.loading || state.playing; }
        var filterIds = ['wwType', 'wwGenre', 'wwDecade', 'wwWatchStatus', 'wwWatcher', 'wwRuntime', 'wwRating', 'wwYear', 'wwLibrary'];
        var storageKey = preferenceKey();
        var savedPreferences = {};

        function preferenceKey() {
            var api = window.ApiClient;
            var server = api && typeof api.serverId === 'function' && api.serverId();
            var user = api && typeof api.getCurrentUserId === 'function' && api.getCurrentUserId();
            return server && user ? 'watchwheel:v1:' + encodeURIComponent(server)
                + ':' + encodeURIComponent(normalizedUserId(user)) : null;
        }

        function ensureContext() {
            if (!state.contextChanged && storageKey === preferenceKey()) return true;
            if (!state.contextChanged) {
                state.contextChanged = true;
                state.request++;
                state.pool = []; state.items = []; state.history = [];
                state.removed.clear(); state.spinning = false; wheelSound.close();
                hideWinner(); renderHistory(); count(); drawWheel(); syncButtons();
            }
            message('Account or server changed. Reload WatchWheel before continuing.');
            return false;
        }

        function readJSON(path) {
            return new Promise(function (resolve, reject) {
                var timer = setTimeout(function () {
                    reject(new Error('Request timed out.'));
                }, 20000);
                Promise.resolve().then(function () {
                    return window.ApiClient.getJSON(window.ApiClient.getUrl(path));
                }).then(function (result) {
                    clearTimeout(timer); resolve(result);
                }, function (error) {
                    clearTimeout(timer); reject(error);
                });
            });
        }

        function writeJSON(method, path, body) {
            return Promise.resolve(window.ApiClient.ajax({
                type: method,
                url: window.ApiClient.getUrl(path),
                data: body == null ? undefined : JSON.stringify(body),
                contentType: 'application/json'
            }));
        }

        function storageNotice(text) { byId('wwStorageNote').textContent = text; }
        function readSaved() {
            if (!storageKey) {
                storageNotice('Settings and recent picks are available for this visit only.');
                return;
            }
            try {
                var saved = JSON.parse(window.localStorage.getItem(storageKey) || '{}');
                if (!saved || typeof saved !== 'object' || Array.isArray(saved)) throw new Error('Invalid saved data');
                savedPreferences = saved.preferences && typeof saved.preferences === 'object'
                    ? saved.preferences : {};
                state.history = Array.isArray(saved.history) ? saved.history.filter(function (entry) {
                    return entry && typeof entry.id === 'string' && entry.id
                        && typeof entry.name === 'string' && typeof entry.pickedAt === 'string'
                        && Number.isFinite(Date.parse(entry.pickedAt));
                }).slice(0, 10).map(function (entry) {
                    return {
                        id: entry.id, name: entry.name, type: entry.type === 'Series' ? 'Series' : 'Movie',
                        episodeId: typeof entry.episodeId === 'string' ? entry.episodeId : '',
                        episode: typeof entry.episode === 'string' ? entry.episode : '', pickedAt: entry.pickedAt
                    };
                }) : [];
                storageNotice('');
            } catch (error) {
                storageNotice('Saved settings could not be read. You can keep using the wheel.');
            }
        }

        function savePreferences() {
            var preferences = {
                avoidRecent: byId('wwAvoidRecent').checked,
                soundEnabled: soundEnabled,
                showChoices: showChoices,
                skin: activeSkin
            };
            filterIds.forEach(function (id) { preferences[id] = byId(id).value; });
            savedPreferences = preferences;
            if (!storageKey || storageKey !== preferenceKey()) return;
            try {
                window.localStorage.setItem(storageKey, JSON.stringify({
                    preferences: preferences, history: state.history
                }));
                storageNotice('');
            } catch (error) {
                storageNotice('This browser could not save your settings. Changes last for this visit only.');
            }
        }

        function restorePreferences() {
            filterIds.forEach(function (id) {
                var select = byId(id);
                var saved = savedPreferences[id];
                if (id === 'wwWatchStatus' && saved === 'all') saved = 'all-unwatched';
                if (typeof saved === 'string' && Array.from(select.options).some(function (option) {
                    return option.value === saved;
                })) {
                    select.value = saved;
                } else if (id === 'wwLibrary' && typeof saved === 'string' && saved) {
                    // Keep the previous scope if access changed or library discovery failed.
                    var unavailable = document.createElement('option');
                    unavailable.value = saved; unavailable.textContent = 'Previously selected library';
                    select.appendChild(unavailable); select.value = saved;
                }
            });
            byId('wwAvoidRecent').checked = savedPreferences.avoidRecent === true;
            soundEnabled = savedPreferences.soundEnabled !== false;
            showChoices = savedPreferences.showChoices !== false;
            activeSkin = savedPreferences.skin === 'classic' ? savedPreferences.skin : 'classic';
            byId('wwShowChoices').checked = showChoices;
            byId('wwSkin').value = activeSkin;
            applyAppearance(false);
            updateSound();
        }

        function applyAppearance(animate) {
            page.setAttribute('data-skin', activeSkin);
            if (page.classList) page.classList.toggle('wwChoicesHidden', !showChoices);
            byId('wwChoicesLibrary').classList.toggle('hidden', !showChoices);
            if (animate && !reducedMotion()) {
                if (page.classList) {
                    page.classList.add('wwThemeChanging');
                    setTimeout(function () { page.classList.remove('wwThemeChanging'); }, 280);
                }
            }
        }

        function setSettingsOpen(open) {
            var panel = byId('wwSettingsPanel');
            panel.classList.toggle('hidden', !open);
            panel.setAttribute('aria-hidden', open ? 'false' : 'true');
            byId('wwSettingsButton').setAttribute('aria-expanded', open ? 'true' : 'false');
            wheelSound.effect(open ? 'settings-open' : 'button-click');
            (open ? byId('wwSettingsClose') : byId('wwSettingsButton')).focus();
        }

        function updateWatchers(watchers) {
            state.watchers = Array.isArray(watchers) ? watchers.filter(function (watcher) {
                return value(watcher, 'Id') && String(value(watcher, 'Name') || '').trim();
            }) : [];
            var select = byId('wwWatcher');
            var selected = select.value;
            select.textContent = '';
            var all = document.createElement('option'); all.value = ''; all.textContent = 'All'; select.appendChild(all);
            state.watchers.forEach(function (watcher) {
                var option = document.createElement('option');
                option.value = String(value(watcher, 'Id'));
                option.textContent = String(value(watcher, 'Name'));
                select.appendChild(option);
            });
            select.value = state.watchers.some(function (watcher) {
                return String(value(watcher, 'Id')) === selected;
            }) ? selected : '';
            renderWatcherList();
        }

        async function refreshWatchers() {
            var previous = byId('wwWatcher').value;
            var response = await readJSON('WatchWheel/Watchers');
            updateWatchers(value(response, 'Watchers') || []);
            var selectionRemoved = previous && !byId('wwWatcher').value;
            savePreferences();
            if (selectionRemoved && state.filtersLoaded && !busy()) await loadCandidates();
        }

        function watcherNotice(text) { byId('wwWatcherMessage').textContent = text || ''; }

        function renderWatcherList() {
            var list = byId('wwWatcherList'); list.textContent = '';
            state.watchers.forEach(function (watcher) {
                var id = String(value(watcher, 'Id')), name = String(value(watcher, 'Name'));
                var row = document.createElement('li'); row.className = 'wwWatcherRow';
                var label = document.createElement('span'); label.textContent = name; row.appendChild(label);
                var rename = document.createElement('button'); rename.type = 'button'; rename.className = 'raised emby-button'; rename.textContent = 'Rename';
                rename.addEventListener('click', async function () {
                    var next = window.prompt('Rename watcher', name);
                    if (next == null) return;
                    try { await writeJSON('PUT', 'WatchWheel/Watchers/' + encodeURIComponent(id), { Name: next }); await refreshWatchers(); watcherNotice('Watcher renamed.'); }
                    catch (error) { watcherNotice('Could not rename watcher. Check that the name is valid and unique.'); }
                });
                var remove = document.createElement('button'); remove.type = 'button'; remove.className = 'raised emby-button'; remove.textContent = 'Delete';
                remove.addEventListener('click', async function () {
                    if (!window.confirm('Delete watcher "' + name + '"? Media will not be deleted.')) return;
                    try { await writeJSON('DELETE', 'WatchWheel/Watchers/' + encodeURIComponent(id)); await refreshWatchers(); watcherNotice('Watcher deleted and assignments cleaned up.'); }
                    catch (error) { watcherNotice('Could not delete watcher.'); }
                });
                row.appendChild(rename); row.appendChild(remove); list.appendChild(row);
            });
        }

        async function openAssignments(item) {
            if (!item || !state.watchers.length || busy()) return;
            state.assignmentItem = item;
            byId('wwAssignmentItem').textContent = nameOf(item);
            byId('wwAssignmentMessage').textContent = 'Loading assignments...';
            byId('wwAssignmentDialog').classList.remove('hidden');
            var options = byId('wwAssignmentOptions'); options.textContent = '';
            try {
                var response = await readJSON('WatchWheel/Assignments/' + encodeURIComponent(idOf(item)));
                var assigned = new Set((value(response, 'WatcherIds') || []).map(String));
                state.watchers.forEach(function (watcher) {
                    var label = document.createElement('label');
                    var checkbox = document.createElement('input'); checkbox.type = 'checkbox';
                    checkbox.value = String(value(watcher, 'Id')); checkbox.checked = assigned.has(checkbox.value);
                    label.appendChild(checkbox); label.appendChild(document.createTextNode(String(value(watcher, 'Name'))));
                    options.appendChild(label);
                });
                byId('wwAssignmentMessage').textContent = '';
                byId('wwAssignmentSave').focus();
            } catch (error) {
                byId('wwAssignmentMessage').textContent = 'Could not load assignments.';
            }
        }

        function closeAssignments() {
            state.assignmentItem = null;
            byId('wwAssignmentDialog').classList.add('hidden');
        }

        async function saveAssignments() {
            if (!state.assignmentItem) return;
            var ids = Array.from(byId('wwAssignmentOptions').querySelectorAll('input:checked')).map(function (input) { return input.value; });
            byId('wwAssignmentMessage').textContent = 'Saving...';
            try {
                await writeJSON('PUT', 'WatchWheel/Assignments/' + encodeURIComponent(idOf(state.assignmentItem)), { WatcherIds: ids });
                wheelSound.effect('toggle'); closeAssignments();
                if (byId('wwWatcher').value) await loadCandidates();
            } catch (error) {
                byId('wwAssignmentMessage').textContent = 'Could not save assignments.';
            }
        }

        function eligibleItems() {
            var recent = new Set(byId('wwAvoidRecent').checked
                ? state.history.map(function (entry) { return entry.id; }) : []);
            return state.pool.filter(function (item) {
                return !state.removed.has(idOf(item)) && !recent.has(idOf(item));
            });
        }

        function filterSnapshot() {
            return JSON.stringify(filterIds.map(function (id) { return byId(id).value; }));
        }

        function filtersPending() {
            return state.appliedFilters !== null && state.appliedFilters !== filterSnapshot();
        }

        function reducedMotion() {
            return typeof window.matchMedia === 'function'
                && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        }

        function filtersChanged() {
            savePreferences(); hideWinner(); syncButtons();
            message(filtersPending() ? '' : poolMessage());
        }

        function resetFilters() {
            if (busy()) return;
            if (!state.filtersLoaded) savedPreferences = {};
            byId('wwType').value = 'both';
            byId('wwGenre').value = '';
            byId('wwDecade').value = '';
            byId('wwWatchStatus').value = 'all-unwatched';
            byId('wwRuntime').value = '';
            byId('wwRating').value = '';
            byId('wwYear').value = '';
            byId('wwLibrary').value = '';
            byId('wwWatcher').value = '';
            byId('wwAvoidRecent').checked = false;
            byId('wwCandidateSearch').value = '';
            return loadCandidates();
        }

        function poolMessage() {
            if (filtersPending()) return '';
            if (!state.pool.length) return byId('wwLibrary').value
                ? 'No matching titles in this library, or it is unavailable. Choose another library or reset filters.'
                : 'No titles match these filters. Try Reset Filters or a different combination.';
            if (eligibleItems().length) return '';
            var remaining = state.pool.filter(function (item) { return !state.removed.has(idOf(item)); });
            return remaining.length && byId('wwAvoidRecent').checked
                ? 'All matching titles are recent picks. Turn off Avoid recent picks or clear history.'
                : 'No choices remain. Adjust your filters or refresh the wheel.';
        }

        function renderCandidates() {
            var eligible = eligibleItems();
            var query = byId('wwCandidateSearch').value.trim().toLocaleLowerCase();
            var matches = eligible.filter(function (item) {
                return nameOf(item).toLocaleLowerCase().includes(query);
            });
            var pageSize = 12;
            var lastPage = Math.max(0, Math.ceil(matches.length / pageSize) - 1);
            state.candidatePage = Math.min(state.candidatePage, lastPage);
            var start = state.candidatePage * pageSize;
            var locked = busy() || filtersPending();
            var list = byId('wwCandidateList');
            list.textContent = '';
            byId('wwCandidateSearch').disabled = busy();
            byId('wwCandidateClear').disabled = busy() || !byId('wwCandidateSearch').value;
            byId('wwRestoreRemoved').disabled = locked || !state.removed.size;
            byId('wwRestoreRemoved').textContent = 'Restore removed (' + state.removed.size + ')';
            byId('wwCandidatePrevious').disabled = busy() || state.candidatePage === 0;
            byId('wwCandidateNext').disabled = busy() || state.candidatePage >= lastPage;
            byId('wwCandidateSummary').textContent = state.loading ? 'Loading titles...'
                : (matches.length ? 'Showing ' + (start + 1) + '–' + Math.min(start + pageSize, matches.length)
                    + ' of ' + matches.length + ' matching titles. ' : 'No matching titles. ')
                    + eligible.length + ' choices on the wheel.';
            byId('wwCandidateEmpty').textContent = state.loading ? '' : filtersPending()
                ? 'Apply Filters to update this list. These are the previous results.'
                : !eligible.length ? poolMessage()
                : !matches.length ? 'No titles match your search. Clear search to see all choices.' : '';
            matches.slice(start, start + pageSize).forEach(function (item) {
                var row = document.createElement('li'); row.className = 'wwCandidateRow';
                var info = document.createElement('div'); info.className = 'wwCandidateInfo';
                var title = document.createElement('strong'); title.textContent = nameOf(item);
                var meta = document.createElement('div'); meta.className = 'winnerMeta';
                var details = [isSeries(item) ? 'TV series' : 'Movie', value(item, 'Year'),
                    value(item, 'IsInProgress') ? 'In progress' : 'Not started', runtimeLabel(item)];
                if (isSeries(item)) details.push('Next: ' + ([episodeCode(item), value(item, 'NextEpisodeName')]
                    .filter(Boolean).join(' • ') || 'Next unwatched episode'));
                meta.textContent = details.filter(Boolean).join(' • ');
                info.appendChild(title); info.appendChild(meta); row.appendChild(info);
                var assign = document.createElement('button');
                assign.type = 'button'; assign.className = 'raised emby-button';
                assign.textContent = 'Watchers'; assign.disabled = locked || !state.watchers.length;
                assign.setAttribute('aria-label', 'Edit watchers assigned to ' + nameOf(item));
                assign.addEventListener('click', function () { openAssignments(item); });
                var remove = document.createElement('button');
                remove.type = 'button'; remove.className = 'raised emby-button';
                remove.textContent = 'Remove'; remove.disabled = locked;
                remove.setAttribute('aria-label', 'Remove ' + nameOf(item) + ' from wheel');
                remove.addEventListener('click', function () {
                    if (busy() || filtersPending()) return;
                    state.removed.add(idOf(item));
                    if (state.winner && idOf(state.winner) === idOf(item)) hideWinner();
                    refreshLocalPool();
                    byId('wwCandidateSearch').focus();
                });
                row.appendChild(remove); row.appendChild(assign); list.appendChild(row);
            });
        }

        function renderHistory() {
            var list = byId('wwHistoryList');
            list.textContent = '';
            byId('wwHistoryEmpty').classList.toggle('hidden', state.history.length > 0);
            state.history.forEach(function (entry) {
                var row = document.createElement('li'); row.className = 'wwHistoryRow';
                var info = document.createElement('div'); info.className = 'wwHistoryInfo';
                var title = document.createElement('strong'); title.textContent = entry.name;
                var detail = document.createElement('div'); detail.className = 'winnerMeta';
                detail.textContent = [entry.type, entry.episode, new Date(entry.pickedAt).toLocaleString()]
                    .filter(Boolean).join(' • ');
                info.appendChild(title); info.appendChild(detail); row.appendChild(info);
                function addButton(label, id) {
                    var button = document.createElement('button');
                    button.type = 'button'; button.className = 'raised emby-button'; button.textContent = label;
                    button.addEventListener('click', function () { if (!busy()) openDetails(id); });
                    row.appendChild(button);
                }
                addButton(entry.type === 'Series' ? 'Series Details' : 'Movie Details', entry.id);
                if (entry.type === 'Series' && entry.episodeId) addButton('Episode Details', entry.episodeId);
                list.appendChild(row);
            });
        }

        function rememberWinner(item) {
            state.history.unshift({
                id: idOf(item), name: nameOf(item), type: isSeries(item) ? 'Series' : 'Movie',
                episodeId: isSeries(item) ? String(value(item, 'NextEpisodeId') || '') : '',
                episode: isSeries(item) ? [episodeCode(item), value(item, 'NextEpisodeName')].filter(Boolean).join(' • ') : '',
                pickedAt: new Date().toISOString()
            });
            state.history = state.history.slice(0, 10);
            savePreferences(); renderHistory(); count();
        }

        function refreshLocalPool() {
            state.items = eligibleItems(); state.rotation = 0;
            count(); drawWheel(); syncButtons(); message(poolMessage());
        }

        function clearHistory() {
            if (busy()) return;
            state.history = []; savePreferences(); renderHistory(); refreshLocalPool();
        }

        function updateSound() {
            wheelSound.enabled(soundEnabled);
            byId('wwSound').textContent = soundEnabled ? 'Enabled' : 'Disabled';
            byId('wwSound').setAttribute('aria-pressed', soundEnabled ? 'true' : 'false');
        }

        function syncButtons() {
            byId('wwSound').disabled = state.contextChanged || !state.filtersLoaded;
            var selectedExtras = ['wwDecade', 'wwRuntime', 'wwRating', 'wwYear'].filter(function (id) { return byId(id).value !== ''; }).length;
            byId('wwMoreFiltersSummary').textContent = 'More filters' + (selectedExtras ? ' (' + selectedExtras + ' selected)' : '');
            var locked = busy();
            var available = eligibleItems().length;
            var pending = filtersPending();
            page.setAttribute('aria-busy', state.loading ? 'true' : 'false');
            byId('wwFilterNote').textContent = pending
                ? 'Changes not applied. The count and wheel still show the previous results.' : '';
            byId('wwApplyFilters').textContent = pending ? 'Apply Filters' : 'Refresh Wheel';
            byId('wwResetFilters').disabled = locked;
            byId('wwSpin').disabled = locked || pending || !available;
            byId('wwApplyFilters').disabled = locked;
            byId('wwAgain').disabled = locked || pending || !available;
            byId('wwRemove').disabled = locked || !state.winner;
            byId('wwAssignWinner').disabled = locked || !state.winner || !state.watchers.length;
            byId('wwPlay').disabled = locked || !playbackTarget(state.winner);
            byId('wwOpen').disabled = locked || !state.winner;
            byId('wwEpisode').disabled = locked || !state.winner;
            byId('wwClearHistory').disabled = locked || !state.history.length;
            byId('wwAvoidRecent').disabled = locked;
            filterIds.forEach(function (id) { byId(id).disabled = locked || !state.filtersLoaded; });
            [['wwTypeAll', 'both'], ['wwTypeMovies', 'movie'], ['wwTypeSeries', 'series']].forEach(function (entry) {
                byId(entry[0]).disabled = locked || !state.filtersLoaded;
                byId(entry[0]).setAttribute('aria-pressed', byId('wwType').value === entry[1] ? 'true' : 'false');
            });
            renderCandidates();
        }
        function playbackMessage(text) { byId('wwPlaybackMessage').textContent = text || ''; }

        function hideWinner() {
            canvas.classList.remove('cinemaWinner');
            clearTimeout(state.playbackTimer);
            state.playbackTimer = null;
            playbackMessage('');
            state.winner = null;
            byId('winnerCard').classList.add('hidden');
            byId('wwWinnerEmpty').classList.remove('hidden');
        }

        function posterUrl(id) {
            if (typeof window.ApiClient.getImageUrl === 'function') {
                return window.ApiClient.getImageUrl(id, { type: 'Primary', maxWidth: 500, quality: 90 });
            }
            return window.ApiClient.getUrl('Items/' + encodeURIComponent(id) + '/Images/Primary');
        }

        function showWinner(item) {
            playbackMessage('');
            state.winner = item;
            var series = isSeries(item);
            var target = playbackTarget(item);
            var code = episodeCode(item);
            var episodeName = value(item, 'NextEpisodeName');
            var episode = [code, episodeName].filter(Boolean).join(' • ');
            byId('winnerSeries').textContent = series ? nameOf(item) : '';
            byId('winnerTitle').textContent = series ? (episodeName || 'Next episode') : nameOf(item);
            byId('winnerEpisode').textContent = series
                ? (target ? code : 'No next episode available. Refresh the wheel.') : '';
            var duration = Number(value(item, 'RunTimeTicks'));
            var knownDuration = Number.isFinite(duration) && duration > 0;
            var parts = [series ? 'TV episode' : 'Movie', value(item, 'Year')].filter(Boolean);
            if (knownDuration) parts.push(Math.ceil(duration / 600000000) + ' min');
            var rating = value(item, 'CommunityRating');
            if (rating != null && Number.isFinite(Number(rating)) && Number(rating) > 0 && Number(rating) <= 10) {
                parts.push('★ ' + Number(rating).toFixed(1) + (series ? ' series' : ''));
            }
            byId('winnerMeta').textContent = parts.join(' • ');
            var hasResume = target && target.ticks > 0;
            var validProgress = hasResume && knownDuration && target.ticks <= duration;
            var resume = hasResume ? 'Resume at ' + timeLabel(target.ticks) : '';
            if (validProgress && duration > target.ticks) resume += ' · ' + Math.ceil((duration - target.ticks) / 600000000) + ' min left';
            byId('winnerResume').textContent = resume;
            var progress = byId('winnerProgress');
            progress.value = validProgress ? target.ticks / duration * 100 : 0;
            progress.classList.toggle('hidden', !validProgress);
            var action = target && target.ticks > 0 ? 'Resume' : 'Play';
            var playLabel = action;
            if (isSeries(item)) {
                playLabel = target
                    ? action + ' ' + (episodeCode(item) || 'Next Episode')
                    : 'No Episode Available';
            }
            byId('wwPlay').textContent = playLabel;
            byId('wwPlay').title = isSeries(item) && target
                ? action + ': ' + (episode || 'Next unwatched episode')
                : playLabel;
            byId('wwOpen').textContent = isSeries(item) ? 'Series Details' : 'Movie Details';
            byId('wwEpisode').classList.toggle('hidden', !isSeries(item) || !target);
            var genres = byId('winnerGenres');
            genres.textContent = '';
            (value(item, 'Genres') || []).forEach(function (genre) {
                var tag = document.createElement('span');
                tag.className = 'winnerGenre';
                tag.textContent = genre;
                genres.appendChild(tag);
            });
            var overview = value(item, 'Overview') || '';
            byId('winnerOverview').textContent = overview;
            byId('winnerDescription').open = false;
            byId('winnerDescription').classList.toggle('hidden', !overview && !(value(item, 'Genres') || []).length);
            byId('winnerDescriptionLabel').textContent = series ? 'About the series' : 'About the movie';
            var poster = byId('winnerPoster');
            var fallback = byId('winnerPosterFallback');
            fallback.textContent = series ? 'TV' : 'MOVIE';
            fallback.classList.remove('hidden');
            poster.style.display = 'block';
            poster.onload = function () { fallback.classList.add('hidden'); };
            poster.onerror = function () { poster.style.display = 'none'; fallback.classList.remove('hidden'); };
            poster.alt = nameOf(item);
            // Artwork and series details deliberately retain the series identifier.
            poster.src = posterUrl(idOf(item));
            byId('winnerCard').classList.remove('hidden');
            byId('wwWinnerEmpty').classList.add('hidden');
            syncButtons();
            byId('winnerCard').scrollIntoView({ behavior: reducedMotion() ? 'auto' : 'smooth', block: 'nearest' });
        }

        function openDetails(id) {
            if (!id) return;
            var serverId = typeof window.ApiClient.serverId === 'function' ? window.ApiClient.serverId() : '';
            window.location.hash = '#/details?id=' + encodeURIComponent(id)
                + (serverId ? '&serverId=' + encodeURIComponent(serverId) : '');
        }

        function tryAndroidPlayback(event, target) {
            var container = byId('wwPlaybackContainer');
            var button = byId('wwPlay');
            var api = window.ApiClient;
            var serverId = typeof api.serverId === 'function' ? api.serverId() : '';
            // Jellyfin's registered items container delegates a real tap to its playback manager.
            // Keep the trusted click synchronous; no synthetic clicks or remote retry.
            if (!event || typeof container.refreshItems !== 'function' || !serverId) {
                if (event) event.stopPropagation();
                playbackMessage('Opening Jellyfin details. Tap Play or Resume there.');
                openDetails(target.id);
                return;
            }
            button.setAttribute('data-id', target.id);
            button.setAttribute('data-serverid', serverId);
            button.setAttribute('data-type', isSeries(state.winner) ? 'Episode' : 'Movie');
            button.setAttribute('data-mediatype', 'Video');
            button.setAttribute('data-isfolder', 'false');
            button.setAttribute('data-positionticks', String(target.ticks));
            button.setAttribute('data-action', target.ticks > 0 ? 'resume' : 'play');
            button.classList.add('itemAction');
            state.playing = true;
            syncButtons();
            playbackMessage('Opening Jellyfin player...');
            state.playbackTimer = setTimeout(function () {
                if (!ensureContext()) { state.playing = false; return; }
                button.classList.remove('itemAction');
                button.setAttribute('data-action', 'none');
                if (!event.defaultPrevented) {
                    state.playing = false;
                    if (page.isConnected) {
                        syncButtons();
                        playbackMessage('Opening Jellyfin details. Tap Play or Resume there.');
                        openDetails(target.id);
                    }
                    return;
                }
                // The event was handled, but that alone does not confirm playback started.
                state.playbackTimer = setTimeout(function () {
                    state.playing = false;
                    if (!ensureContext() || !page.isConnected) return;
                    syncButtons();
                    playbackMessage(document.hidden ? '' : 'If playback has not started, use '
                        + (isSeries(state.winner) ? 'Episode Details' : 'Movie Details') + ' below.');
                }, 5000);
            }, 0);
        }

        async function playWinner(event) {
            if (!ensureContext()) { if (event) event.stopPropagation(); return; }
            if (busy() || !state.winner) {
                if (event) event.stopPropagation();
                return;
            }
            var target = playbackTarget(state.winner);
            if (!target) {
                if (event) event.stopPropagation();
                playbackMessage('No episode is available. Refresh the wheel.');
                return;
            }
            if (isAndroidClient()) {
                try {
                    tryAndroidPlayback(event, target);
                } catch (error) {
                    if (event) event.stopPropagation();
                    byId('wwPlay').classList.remove('itemAction');
                    state.playing = false;
                    syncButtons();
                    playbackMessage('Could not open the Android player. Use '
                        + (isSeries(state.winner) ? 'Episode Details' : 'Movie Details') + ' below.');
                }
                return;
            }
            if (event) event.stopPropagation();
            state.playing = true;
            syncButtons();
            playbackMessage(target.ticks > 0 ? 'Resuming playback...' : 'Starting playback...');
            try {
                await sendSessionPlayback(target);
                if (!ensureContext()) return;
                playbackMessage('Playback requested. If it does not start, use '
                    + (isSeries(state.winner) ? 'Episode Details' : 'Movie Details') + ' below.');
            } catch (error) {
                if (!ensureContext()) return;
                console.error('Watch Wheel playback failed:', error);
                playbackMessage((error.message || 'Could not start playback here.') + ' Use '
                    + (isSeries(state.winner) ? 'Episode Details' : 'Movie Details')
                    + ' below.');
            } finally {
                state.playing = false;
                syncButtons();
            }
        }

        async function loadFilters() {
            var results = await Promise.all([readJSON('WatchWheel/Filters'), readJSON('WatchWheel/Watchers')]);
            var result = results[0];
            if (!ensureContext()) throw new Error('Account changed.');
            if (!result || ['Genres', 'Decades', 'Years', 'Libraries'].some(function (key) {
                var options = value(result, key);
                return options != null && !Array.isArray(options);
            })) throw new Error('Invalid filter options.');
            function populate(id, items, label, suffix) {
                var select = byId(id);
                select.textContent = '';
                var any = document.createElement('option');
                any.value = ''; any.textContent = label; select.appendChild(any);
                items.forEach(function (item) {
                    var option = document.createElement('option');
                    option.value = String(item); option.textContent = String(item) + suffix;
                    select.appendChild(option);
                });
            }
            populate('wwGenre', value(result, 'Genres') || [], 'Any Genre', '');
            populate('wwDecade', value(result, 'Decades') || [], 'Any Decade', 's');
            populate('wwYear', value(result, 'Years') || [], 'Any year', '');
            var librarySelect = byId('wwLibrary');
            librarySelect.textContent = '';
            var allLibraries = document.createElement('option');
            allLibraries.value = ''; allLibraries.textContent = 'All libraries'; librarySelect.appendChild(allLibraries);
            (value(result, 'Libraries') || []).forEach(function (library) {
                var id = value(library, 'Id');
                if (!id) return;
                var option = document.createElement('option');
                option.value = String(id); option.textContent = String(value(library, 'Name') || 'Library');
                librarySelect.appendChild(option);
            });
            updateWatchers(value(results[1], 'Watchers') || []);
        }

        async function loadCandidates() {
            if (busy() || !ensureContext()) return;
            var request = ++state.request;
            state.loading = true;
            hideWinner(); syncButtons();
            message(state.filtersLoaded ? 'Loading your Jellyfin library...' : 'Loading filters...');
            try {
                if (!state.filtersLoaded) {
                    await loadFilters();
                    if (!ensureContext() || request !== state.request) return;
                    restorePreferences();
                    state.filtersLoaded = true;
                }
                savePreferences();
                state.removed.clear(); state.candidatePage = 0;
                var appliedFilters = filterSnapshot();
                var params = new URLSearchParams();
                params.set('type', byId('wwType').value || 'both');
                if (byId('wwLibrary').value) params.set('libraryId', byId('wwLibrary').value);
                if (byId('wwGenre').value) params.set('genre', byId('wwGenre').value);
                if (byId('wwDecade').value) params.set('decade', byId('wwDecade').value);
                if (byId('wwWatcher').value) params.set('watcherId', byId('wwWatcher').value);
                var maxMinutes = Number(byId('wwRuntime').value);
                var minimumRating = Number(byId('wwRating').value);
                var releaseYear = byId('wwYear').value;
                var watchStatus = byId('wwWatchStatus').value || 'all-unwatched';
                params.set('watchStatus', watchStatus);
                var result = await readJSON('WatchWheel/Items?' + params);
                if (!ensureContext() || request !== state.request) return;
                if (!Array.isArray(value(result, 'Items'))) throw new Error('Invalid title response.');
                state.appliedFilters = appliedFilters;
                state.pool = (value(result, 'Items') || []).filter(function (item) {
                    if (!item || !idOf(item)) return false;
                    if (!matchesRuntime(item, maxMinutes) || !matchesRating(item, minimumRating)) return false;
                    if (releaseYear && String(value(item, 'Year')) !== releaseYear) return false;
                    return true;
                });
                state.items = eligibleItems();
                state.rotation = 0;
                message(poolMessage());
            } catch (error) {
                if (!ensureContext() || request !== state.request) return;
                state.items = []; state.pool = [];
                console.error('Watch Wheel request failed:', error);
                var status = error && (error.status || error.statusCode);
                message(status === 401 || status === 403 ? 'Jellyfin access was denied. Sign in again or check your access.'
                    : 'Unable to load ' + (state.filtersLoaded ? 'titles' : 'filters') + '. Try Refresh Wheel again.');
            } finally {
                state.loading = false;
                count(); drawWheel(); syncButtons();
            }
        }

        function drawWheel() {
            var cx = canvas.width / 2, cy = canvas.height / 2;
            var rim = Math.min(cx, cy) - 14, radius = rim - 22;
            context.clearRect(0, 0, canvas.width, canvas.height);
            context.beginPath(); context.arc(cx, cy, rim, 0, TWO_PI);
            context.fillStyle = '#171513'; context.fill();
            context.strokeStyle = '#987346'; context.lineWidth = 2; context.stroke();
            if (!state.items.length) {
                context.fillStyle = '#dbc7a3'; context.font = '600 24px sans-serif';
                context.textAlign = 'center'; context.textBaseline = 'middle';
                context.fillText('No choices', cx, cy + radius * 0.45);
            } else {
                var arc = TWO_PI / state.items.length;
                // Same angular origin and equal slices as the selection/landing calculation.
                var pointerAngle = ((-Math.PI / 2 - state.rotation) % TWO_PI + TWO_PI) % TWO_PI;
                var active = Math.min(state.items.length - 1, Math.floor(pointerAngle / arc));
                var palette = ['#292723', '#493726', '#242426', '#3b3026'];
                state.items.forEach(function (item, index) {
                    var start = state.rotation + index * arc;
                    var highlighted = index === active;
                    context.save();
                    context.beginPath(); context.moveTo(cx, cy);
                    context.arc(cx, cy, radius, start, start + arc); context.closePath();
                    context.fillStyle = highlighted ? '#926534' : palette[index % palette.length];
                    context.fill(); context.strokeStyle = highlighted ? '#f0c581' : '#826443';
                    context.lineWidth = highlighted ? 1.8 : 0.8; context.stroke();
                    context.clip();
                    var font = Math.max(6, Math.min(19, Math.floor(arc * radius * 0.4)));
                    context.font = '500 ' + font + 'px sans-serif';
                    var title = nameOf(item), maxWidth = radius * 0.51;
                    if (context.measureText(title).width > maxWidth) {
                        while (title.length && context.measureText(title + '…').width > maxWidth) {
                            title = title.slice(0, -1);
                        }
                        title += '…';
                    }
                    var middle = start + arc / 2;
                    var left = Math.cos(middle) < 0;
                    context.translate(cx, cy); context.rotate(middle + (left ? Math.PI : 0));
                    context.fillStyle = '#fff0d8';
                    context.textAlign = left ? 'left' : 'right'; context.textBaseline = 'middle';
                    context.fillText(title, (left ? -1 : 1) * (radius - 16), 0);
                    context.restore();
                });
            }
            context.beginPath(); context.arc(cx, cy, radius + 2, 0, TWO_PI);
            context.strokeStyle = '#b68b53'; context.lineWidth = 2; context.stroke();
            // A fixed number of small lights keeps rendering cost steady for large pools.
            for (var light = 0; light < 48; light++) {
                var angle = light * TWO_PI / 48;
                var x = cx + Math.cos(angle) * (rim - 10);
                var y = cy + Math.sin(angle) * (rim - 10);
                context.beginPath(); context.arc(x, y, 5, 0, TWO_PI);
                context.fillStyle = 'rgba(226,161,77,0.14)'; context.fill();
                context.beginPath(); context.arc(x, y, 2.1, 0, TWO_PI);
                context.fillStyle = state.items.length ? '#f3cb8b' : '#796449'; context.fill();
            }
        }

        function spin() {
            if (busy() || filtersPending()) return;
            state.items = eligibleItems();
            if (!state.items.length) { syncButtons(); message(poolMessage()); return; }
            wheelSound.stop(); wheelSound.prime();
            hideWinner(); state.spinning = true; syncButtons(); message('Spinning...');
            var index = Math.floor(Math.random() * state.items.length);
            var arc = TWO_PI / state.items.length;
            var start = state.rotation;
            var desired = -Math.PI / 2 - (index * arc + arc / 2);
            var delta = ((desired - start) % TWO_PI + TWO_PI) % TWO_PI;
            var end = start + delta + TWO_PI * (6 + Math.floor(Math.random() * 3));
            var duration = reducedMotion() ? 0 : 5000 + Math.random() * 1300;
            var started = performance.now();
            wheelSound.spin(duration);
            function animate(now) {
                if (!ensureContext()) return;
                if (!page.isConnected) { wheelSound.close(); state.spinning = false; syncButtons(); return; }
                var progress = duration === 0 ? 1 : Math.min((now - started) / duration, 1);
                state.rotation = start + (end - start) * (1 - Math.pow(1 - progress, 5));
                drawWheel();
                if (progress < 1) { requestAnimationFrame(animate); return; }
                state.rotation = ((end % TWO_PI) + TWO_PI) % TWO_PI;
                state.spinning = false;
                var winner = state.items[index];
                rememberWinner(winner);
                message(eligibleItems().length ? 'The wheel has spoken.'
                    : 'The wheel has spoken. ' + poolMessage());
                showWinner(winner);
                wheelSound.win();
                if (!reducedMotion()) canvas.classList.add('cinemaWinner');
            }
            requestAnimationFrame(animate);
        }

        function removeWinner() {
            if (busy() || !state.winner) return;
            var id = idOf(state.winner);
            state.removed.add(id);
            hideWinner(); refreshLocalPool();
        }

        async function start() {
            ['click', 'change', 'input'].forEach(function (type) {
                page.addEventListener(type, function (event) {
                    if (!ensureContext()) { event.preventDefault(); event.stopImmediatePropagation(); }
                }, true);
            });
            page.addEventListener('viewshow', ensureContext);
            page.addEventListener('viewhide', function () { wheelSound.close(); });
            if (typeof document.addEventListener === 'function') {
                document.addEventListener('visibilitychange', function onVisibilityChange() {
                    if (document.hidden) wheelSound.stop();
                    if (!page.isConnected) { wheelSound.close(); document.removeEventListener('visibilitychange', onVisibilityChange); }
                });
            }
            byId('wwSound').addEventListener('click', function () {
                if (!state.filtersLoaded || !ensureContext()) return;
                soundEnabled = !soundEnabled; updateSound(); savePreferences();
                if (soundEnabled) wheelSound.prime();
            });
            byId('wwSettingsButton').addEventListener('click', function () { setSettingsOpen(true); });
            byId('wwSettingsClose').addEventListener('click', function () { setSettingsOpen(false); });
            byId('wwSettingsPanel').addEventListener('keydown', function (event) {
                if (event.key === 'Escape') setSettingsOpen(false);
            });
            byId('wwShowChoices').addEventListener('change', function () {
                showChoices = byId('wwShowChoices').checked;
                wheelSound.effect('toggle'); applyAppearance(true); savePreferences();
            });
            byId('wwSkin').addEventListener('change', function () {
                activeSkin = byId('wwSkin').value === 'classic' ? 'classic' : 'classic';
                wheelSound.effect('filter-change'); applyAppearance(true); savePreferences();
            });
            byId('wwWatcherCreate').addEventListener('submit', async function (event) {
                event.preventDefault();
                var input = byId('wwWatcherName'), name = input.value;
                try {
                    await writeJSON('POST', 'WatchWheel/Watchers', { Name: name });
                    input.value = ''; await refreshWatchers(); watcherNotice('Watcher created.');
                } catch (error) {
                    watcherNotice('Could not create watcher. Check that the name is valid and unique.');
                }
            });
            byId('wwAssignmentCancel').addEventListener('click', closeAssignments);
            byId('wwAssignmentSave').addEventListener('click', saveAssignments);
            byId('wwAssignmentDialog').addEventListener('keydown', function (event) {
                if (event.key === 'Escape') closeAssignments();
            });
            readSaved(); renderHistory();
            [['wwTypeAll', 'both'], ['wwTypeMovies', 'movie'], ['wwTypeSeries', 'series']].forEach(function (entry) {
                byId(entry[0]).addEventListener('click', function () {
                    if (busy() || !state.filtersLoaded) return;
                    byId('wwType').value = entry[1]; filtersChanged();
                });
            });
            var browseTabs = ['wwChoicesTab', 'wwRecentTab'];
            function selectBrowseTab(index) {
                browseTabs.forEach(function (id, i) {
                    byId(id).setAttribute('aria-selected', i === index ? 'true' : 'false');
                    byId(id).setAttribute('tabindex', i === index ? '0' : '-1');
                });
                byId('wwChoicesPanel').classList.toggle('hidden', index !== 0);
                byId('wwRecentPanel').classList.toggle('hidden', index !== 1);
            }
            browseTabs.forEach(function (id, index) {
                byId(id).addEventListener('click', function () { selectBrowseTab(index); });
                byId(id).addEventListener('keydown', function (event) {
                    var next;
                    if (event.key === 'ArrowRight' || event.key === 'ArrowLeft') next = 1 - index;
                    else if (event.key === 'Home') next = 0;
                    else if (event.key === 'End') next = 1;
                    else return;
                    event.preventDefault(); selectBrowseTab(next); byId(browseTabs[next]).focus();
                });
            });
            byId('wwCandidateSearch').addEventListener('input', function () {
                state.candidatePage = 0; renderCandidates();
            });
            byId('wwCandidateClear').addEventListener('click', function () {
                if (busy()) return;
                byId('wwCandidateSearch').value = ''; state.candidatePage = 0;
                renderCandidates(); byId('wwCandidateSearch').focus();
            });
            byId('wwCandidatePrevious').addEventListener('click', function () {
                if (busy()) return;
                state.candidatePage = Math.max(0, state.candidatePage - 1); renderCandidates();
            });
            byId('wwCandidateNext').addEventListener('click', function () {
                if (busy()) return;
                state.candidatePage++; renderCandidates();
            });
            byId('wwRestoreRemoved').addEventListener('click', function () {
                if (busy() || filtersPending()) return;
                state.removed.clear(); refreshLocalPool();
            });
            filterIds.forEach(function (id) { byId(id).addEventListener('change', filtersChanged); });
            byId('wwAvoidRecent').addEventListener('change', function () {
                if (busy()) return;
                savePreferences(); refreshLocalPool();
            });
            byId('wwClearHistory').addEventListener('click', clearHistory);
            byId('wwApplyFilters').addEventListener('click', loadCandidates);
            byId('wwResetFilters').addEventListener('click', resetFilters);
            byId('wwSpin').addEventListener('click', spin);
            byId('wwAgain').addEventListener('click', spin);
            byId('wwRemove').addEventListener('click', removeWinner);
            byId('wwAssignWinner').addEventListener('click', function () { openAssignments(state.winner); });
            byId('wwPlay').addEventListener('click', playWinner);
            byId('wwOpen').addEventListener('click', function () {
                if (!busy() && state.winner) openDetails(idOf(state.winner));
            });
            byId('wwEpisode').addEventListener('click', function () {
                var target = playbackTarget(state.winner);
                if (!busy() && target) openDetails(target.id);
            });
            drawWheel();
            await loadCandidates();
        }
        return { start: start };
    }

    var initialized = new WeakSet();
    window.WatchWheelApp = {
        init: function (page) {
            if (!page || initialized.has(page)) return;
            initialized.add(page);
            createApp(page).start().catch(function (error) {
                console.error('Watch Wheel initialization failed:', error);
                var message = page.querySelector('#wwMessage');
                if (message) message.textContent = 'Watch Wheel could not initialize. Reload the page.';
            });
        }
    };
})();
